# Língua Portuguesa — L18 onda 1: pontuação (LP01) e concordância (LP02). Itens curtos; comentário objetivo (regra + pegadinha).
Q = []
TAILS=[" Essa seria a orientação predominante nas gramáticas normativas.",
 " Trata-se de entendimento corrente na norma-padrão.",
 " Tal solução decorreria, segundo esse entendimento, da estrutura da frase.",
 " Essa seria a leitura mais aceita pelos gramáticos."]
SHORT=[" Isso é consenso."," Essa é a regra geral."," Trata-se de prática corrente."," Esse é o uso padrão."]
def tail(E,C,i):
    gap=len(C)-len(E)
    if len(E) < 0.97*len(C) and gap > 60: return E+TAILS[i%len(TAILS)]
    if len(E) < 0.95*len(C) and gap > 8: return E+SHORT[i%len(SHORT)]
    return E
FG={"tipo":"gramatica","ref":"norma-padrão (Bechara; Cegalla; Cunha e Cintra)","versao":"conhecimento do autor","conferida":"conhecimento"}
def P(ponto, arts, padC, padE, dif, C, E, com, terro, tag):
    ex={"fonte":FG,"risco":["doutrina_conhecimento"]}
    E = tail(E, C, len(Q))
    padC = padE if padC == 'conceito_correto' else padC
    Q.append((ponto, arts, "C", padC, dif, C, com, "", tag, ex))
    Q.append((ponto, arts, "E", padE, dif, E, com, terro, tag, ex))
_n=[0]
def S(ponto, atom, padE, dif, C, E, com, terro):
    _n[0]+=1
    P(ponto,[str(atom)],"conceito_correto",padE,dif,C,E,com,terro,f"p{_n[0]:02d}")
def PT(atom, padE, dif, C, E, com, terro): S("LP01", atom, padE, dif, C, E, com, terro)
def CN(atom, padE, dif, C, E, com, terro): S("LP02", atom, padE, dif, C, E, com, terro)
# ================= PONTUAÇÃO =================
# átomo 1: sujeito, verbo, complementos
PT(1,"norma_culta",2,"No período 'Os deputados da bancada, aprovaram a emenda', a vírgula após 'bancada' é inadequada, pois separa o sujeito do verbo.","No período 'Os deputados da bancada, aprovaram a emenda', a vírgula após 'bancada' é exigida pela norma-padrão para marcar o fim do sujeito.","Vírgula não separa sujeito de verbo.","trata a vírgula indevida como obrigatória")
PT(1,"norma_culta",3,"Em 'A proposta, apresentada ontem pelo relator, foi rejeitada', as vírgulas isolam termo intercalado entre o sujeito e o verbo.","Em 'A proposta, apresentada ontem pelo relator, foi rejeitada', uma das vírgulas poderia ser suprimida, mantendo-se a outra, sem prejuízo da correção.","Intercalado: duas vírgulas ou nenhuma.","aceita uma só vírgula no intercalado")
PT(1,"norma_culta",3,"O período 'O relator afirmou que o texto, apesar das críticas, seria votado' está correto quanto à pontuação, pois o termo intercalado vem isolado por duas vírgulas.","O período 'O relator afirmou que o texto, apesar das críticas seria votado' está correto quanto à pontuação, pois a vírgula separa o sujeito do verbo.","Faltou a vírgula de fechamento do intercalado.","omite a segunda vírgula")
PT(1,"norma_culta",3,"No período 'A comissão informou, aos parlamentares o resultado', a vírgula depois de 'informou' deve ser suprimida, pois separa o verbo de seus complementos.","No período 'A comissão informou, aos parlamentares o resultado', a vírgula depois de 'informou' é obrigatória, pois isola o complemento 'aos parlamentares'.","Verbo e complementos não se separam por vírgula.","trata vírgula indevida como obrigatória")
PT(1,"norma_culta",4,"No período 'Que o projeto seja votado hoje, é desejo da maioria', a vírgula é indevida, pois separa a oração subjetiva do verbo da principal.","No período 'Que o projeto seja votado hoje, é desejo da maioria', a vírgula é obrigatória, pois marca o deslocamento da oração subjetiva.","Oração subjetiva é sujeito: sem vírgula.","trata sujeito oracional como deslocado")
PT(1,"norma_culta",2,"Em 'Senhores deputados, a sessão está aberta', a vírgula isola o vocativo.","Em 'Senhores deputados, a sessão está aberta', a vírgula separa o sujeito do verbo e deveria ser suprimida.","Vocativo vem isolado por vírgula.","confunde vocativo com sujeito")
# átomo 2: adjetivas e apostos
PT(2,"confusao_instituto",3,"Em 'Os servidores que faltaram foram advertidos', a ausência de vírgulas indica que só parte dos servidores faltou e foi advertida.","Em 'Os servidores que faltaram foram advertidos', a ausência de vírgulas indica que o conjunto inteiro de servidores faltou e foi advertido.","Sem vírgulas = restritiva = parte.","inverte restritiva e explicativa")
PT(2,"confusao_instituto",3,"Em 'Os servidores, que faltaram, foram advertidos', as vírgulas indicam que o conjunto inteiro de servidores faltou.","Em 'Os servidores, que faltaram, foram advertidos', as vírgulas indicam que só parte dos servidores faltou.","Entre vírgulas = explicativa = generaliza.","inverte restritiva e explicativa")
PT(2,"confusao_instituto",3,"Em 'O projeto, que foi enviado ontem, tramita em regime de urgência', a oração entre vírgulas é explicativa e sua supressão não altera o sentido essencial da afirmação principal.","Em 'O projeto, que foi enviado ontem, tramita em regime de urgência', a oração entre vírgulas é restritiva e sua supressão altera o sentido essencial da afirmação principal.","Explicativa é acessória.","classifica explicativa como restritiva")
PT(2,"troca_efeito",4,"Em 'A emenda que o plenário rejeitou será reapresentada', a inserção de vírgulas em torno de 'que o plenário rejeitou' alteraria o sentido, pois transformaria a oração restritiva em explicativa.","Em 'A emenda que o plenário rejeitou será reapresentada', a inserção de vírgulas em torno de 'que o plenário rejeitou' não alteraria o sentido, pois a oração continuaria restritiva.","Vírgulas mudam o valor da oração.","afirma que a vírgula não muda o sentido")
PT(2,"excecao_omitida",3,"Na frase 'O parecer, o qual foi aprovado, segue ao Plenário', as vírgulas são obrigatórias, por isolarem oração adjetiva explicativa.","Na frase 'O parecer, o qual foi aprovado, segue ao Plenário', as vírgulas são facultativas, por isolarem oração adjetiva explicativa.","Explicativa: vírgulas obrigatórias.","admite vírgula isolada")
PT(2,"confusao_instituto",3,"Em 'O poeta Camões escreveu Os Lusíadas', não há vírgula porque 'Camões' é aposto restritivo, que identifica o poeta em questão.","Em 'O poeta Camões escreveu Os Lusíadas', devem-se inserir vírgulas em torno de 'Camões', pois apostos são isolados por vírgulas.","Aposto restritivo não leva vírgula.","generaliza vírgula no aposto")
# átomo 3: adjuntos adverbiais e conectivos
PT(3,"excecao_omitida",3,"Em 'Ontem o plenário votou a matéria', a vírgula depois de 'Ontem' é facultativa, por tratar-se de adjunto adverbial curto antecipado.","Em 'Ontem o plenário votou a matéria', a vírgula depois de 'Ontem' é obrigatória, por tratar-se de adjunto adverbial antecipado.","Adjunto curto antecipado: facultativa.","chama facultativa de obrigatória")
PT(3,"regra_como_excecao",3,"Em 'Apesar das divergências entre os partidos que compõem a base, o governo aprovou a reforma', a vírgula após 'base' é recomendada, por separar longo adjunto adverbial antecipado.","Em 'Apesar das divergências entre os partidos que compõem a base, o governo aprovou a reforma', a vírgula após 'base' é indevida, pois adjuntos adverbiais antecipados não se separam do restante da frase.","Adjunto longo antecipado: vírgula.","veta vírgula no adjunto longo")
PT(3,"excecao_omitida",3,"Em 'O governo, em razão da crise, adiou a votação', as duas vírgulas formam um par: suprimir apenas a primeira ou a segunda tornaria a pontuação inadequada.","Em 'O governo, em razão da crise, adiou a votação', é possível suprimir apenas a vírgula depois de 'governo', mantendo a outra, sem prejuízo da pontuação.","Intercalado: vírgulas em par.","admite vírgula isolada")
PT(3,"norma_culta",3,"Em 'A proposta é, portanto, inconstitucional', as duas vírgulas isolam a conjunção conclusiva intercalada.","Em 'A proposta é, portanto, inconstitucional', a supressão de uma só das vírgulas manteria a correção do período.","Conjunção intercalada: duas vírgulas.","aceita uma só vírgula")
PT(3,"regra_como_excecao",2,"Em 'O texto foi aprovado, mas ainda depende de sanção', a vírgula antes de 'mas' é adequada, pois a conjunção adversativa liga orações coordenadas.","Em 'O texto foi aprovado, mas ainda depende de sanção', a vírgula antes de 'mas' é inadequada, pois conjunções adversativas dispensam vírgula.","Adversativa: vírgula antes.","veta vírgula antes da adversativa")
PT(3,"excecao_omitida",3,"Em 'O relator leu o parecer, e os deputados o aprovaram', a vírgula antes de 'e' é admitida, pois a conjunção liga orações de sujeitos diferentes.","Em 'O relator leu o parecer, e os deputados o aprovaram', a vírgula antes de 'e' é inadequada, pois não se emprega vírgula antes dessa conjunção.","'e' com sujeitos diferentes admite vírgula.","veta toda vírgula antes de 'e'")
# átomo 4: adverbiais, explicativas, enumeração, elipse, datas
PT(4,"norma_culta",3,"Em 'Quando o relator concluiu a leitura, o presidente abriu a discussão', a vírgula é adequada porque a oração subordinada adverbial está anteposta à principal.","Em 'Quando o relator concluiu a leitura, o presidente abriu a discussão', a vírgula é indevida, pois separa a oração subordinada da principal.","Adverbial anteposta: vírgula.","veta a vírgula da adverbial anteposta")
PT(4,"excecao_omitida",3,"Em 'O presidente abriu a discussão quando o relator concluiu a leitura', a ausência de vírgula é admitida, pois a oração subordinada adverbial está posposta.","Em 'O presidente abriu a discussão quando o relator concluiu a leitura', a vírgula antes de 'quando' é obrigatória, pois a oração subordinada adverbial está posposta.","Adverbial posposta: vírgula facultativa.","chama facultativa de obrigatória")
PT(4,"norma_culta",3,"Em 'O texto foi aprovado, ou seja, não haverá novas alterações', as vírgulas antes e depois de 'ou seja' isolam expressão explicativa.","Em 'O texto foi aprovado, ou seja não haverá novas alterações', a pontuação está correta, pois a expressão explicativa dispensa a segunda vírgula.","'Ou seja' é isolado dos dois lados.","dispensa a vírgula depois da expressão")
PT(4,"regra_como_excecao",2,"Em 'Não houve sessão, pois faltou quórum', a vírgula antes de 'pois' é adequada, por tratar-se de conjunção explicativa.","Em 'Não houve sessão, pois faltou quórum', a vírgula antes de 'pois' é indevida, pois essa palavra introduz oração subordinada.","'Pois' explicativo é coordenativo: vírgula.","trata 'pois' como subordinativo")
PT(4,"regra_como_excecao",2,"Em 'Foram aprovados o orçamento, a LDO e o PPA', não há vírgula antes do 'e' que encerra a enumeração.","Em 'Foram aprovados o orçamento, a LDO e o PPA', a vírgula antes do 'e' que encerra a enumeração é obrigatória.","'E' final da enumeração dispensa vírgula.","exige vírgula antes do 'e'")
PT(4,"confusao_instituto",3,"Em 'O Senado aprovou o projeto; a Câmara, a emenda', a vírgula após 'Câmara' marca a elipse do verbo 'aprovou'.","Em 'O Senado aprovou o projeto; a Câmara, a emenda', a vírgula após 'Câmara' marca o fim do sujeito e é indevida.","Vírgula pode marcar elipse do verbo.","confunde elipse com separação sujeito-verbo")
# átomo 5: ponto e vírgula, dois-pontos, travessão, parênteses, aspas
PT(5,"restricao_indevida",3,"O ponto e vírgula pode separar itens de uma enumeração extensa que já contenham vírgulas internas.","O ponto e vírgula não pode separar itens de uma enumeração que contenham vírgulas internas, ficando restrito ao uso entre orações coordenadas.","Ponto e vírgula organiza enumerações longas.","restringe o ponto e vírgula")
PT(5,"restricao_indevida",2,"Os dois-pontos podem introduzir enumeração, citação ou explicação, como em 'Dois temas dominaram a pauta: saúde e educação'.","Os dois-pontos podem introduzir enumeração e citação, mas não explicação, como em 'Dois temas dominaram a pauta: saúde e educação'.","Dois-pontos também introduzem explicação.","retira a explicação dos usos")
PT(5,"norma_culta",3,"Em 'Os temas foram: saúde e educação', os dois-pontos são inadequados, pois separam o verbo de seu complemento.","Em 'Os temas foram: saúde e educação', os dois-pontos são obrigatórios, pois a enumeração exige esse sinal depois de verbo.","Dois-pontos não separam verbo e complemento.","exige dois-pontos após o verbo")
PT(5,"restricao_indevida",3,"O travessão duplo pode isolar termo intercalado com ênfase maior do que a das vírgulas.","O travessão duplo só pode isolar apostos, não admitindo o isolamento de adjunto adverbial intercalado.","Travessão duplo isola intercalados com realce.","restringe o travessão a apostos")
PT(5,"confusao_instituto",2,"Os parênteses isolam informação acessória, de menor relevância para o desenvolvimento do texto.","Os parênteses isolam informação de maior relevância do que a isolada por vírgulas, destacando-a no desenvolvimento do texto.","Parênteses = acessório.","inverte a ênfase dos parênteses")
PT(5,"restricao_indevida",2,"As aspas podem indicar citação, estrangeirismo ou emprego irônico de um termo.","As aspas indicam citação textual, sendo inadequadas para marcar estrangeirismo ou emprego irônico de um termo.","Aspas têm vários usos.","restringe o uso das aspas")
# átomo 6: pontuação e sentido
PT(6,"troca_efeito",2,"As frases 'Não, quero ajuda' e 'Não quero ajuda' têm sentidos diferentes, em razão da posição da vírgula.","As frases 'Não, quero ajuda' e 'Não quero ajuda' têm o mesmo sentido, pois a vírgula não altera o significado.","Vírgula muda sentido.","afirma mesmo sentido")
PT(6,"troca_efeito",2,"Em 'Vamos comer, João', o termo 'João' é vocativo; em 'Vamos comer João', passa a ser objeto direto, e a vírgula é o que muda a relação sintática.","Em 'Vamos comer, João', o termo 'João' é objeto direto; em 'Vamos comer João', passa a ser vocativo, e a vírgula é o que muda a relação sintática.","Com vírgula: vocativo.","inverte vocativo e objeto")
PT(6,"norma_culta",3,"No período 'O ministro disse, que votaria contra', a vírgula é indevida, pois separa o verbo da oração subordinada substantiva objetiva direta.","No período 'O ministro disse, que votaria contra', a vírgula é obrigatória, pois a oração subordinada substantiva objetiva direta deve vir isolada.","Objetiva direta não se isola.","trata vírgula indevida como obrigatória")
PT(6,"norma_culta",2,"Na expressão 'Brasília, 16 de outubro de 2026', a vírgula após o local é obrigatória.","Na expressão 'Brasília, 16 de outubro de 2026', a vírgula após o local é facultativa.","Local e data: vírgula obrigatória.","admite vírgula isolada")
PT(6,"norma_culta",3,"Em 'O projeto, porém, foi vetado', as vírgulas são obrigatórias, pois 'porém' está deslocado para o interior da oração.","Em 'O projeto, porém, foi vetado', as vírgulas são dispensáveis, pois 'porém' deslocado para o interior da oração não exige isolamento.","Conjunção deslocada: duas vírgulas.","dispensa vírgulas")
PT(6,"norma_culta",3,"Em 'Nem o relator, nem o presidente compareceram', a vírgula antes do segundo 'nem' é admitida, por haver repetição da conjunção.","Em 'Nem o relator, nem o presidente compareceram', a vírgula antes do segundo 'nem' é inadequada, pois a conjunção aditiva dispensa vírgula.","'Nem... nem' admite vírgula.","veta a vírgula da repetição")
# ================= CONCORDÂNCIA =================
# átomo 7: sujeito composto
CN(7,"norma_culta",2,"A frase 'O ministro e o secretário chegaram à Câmara' atende à norma-padrão quanto à concordância verbal.","A frase 'O ministro e o secretário chegou à Câmara' atende à norma-padrão quanto à concordância verbal.","Composto anteposto: plural.","verbo no singular com sujeito composto")
CN(7,"excecao_omitida",3,"Em 'O ministro ou o secretário assinará o ato', o verbo no singular é adequado se houver ideia de exclusão, isto é, se apenas um deles assinar.","Em 'O ministro ou o secretário assinará o ato', o verbo no plural é obrigatório, pois o sujeito é composto.","'Ou' com exclusão: singular.","exige plural com 'ou' exclusivo")
CN(7,"confusao_instituto",3,"Em 'O presidente, com os líderes, decidiu a pauta', o verbo concorda no singular, pois 'com os líderes' é adjunto de companhia.","Em 'O presidente, com os líderes, decidiu a pauta', o verbo deveria estar no plural, pois 'com' equivale à conjunção 'e'.","'Com' não forma sujeito composto.","iguala 'com' a 'e'")
CN(7,"excecao_omitida",3,"Em 'A calma, a serenidade, a paciência marcou sua atuação', o verbo no singular é admitido, por haver núcleos sinônimos em gradação.","Em 'A calma, a serenidade, a paciência marcou sua atuação', o verbo no singular é inadmissível, pois sujeito composto exige verbo no plural.","Núcleos sinônimos/gradação: singular admitido.","nega a exceção")
CN(7,"norma_culta",2,"Em 'Eu e o relator votamos contra', o verbo concorda na primeira pessoa do plural, pois a primeira pessoa prevalece.","Em 'Eu e o relator votaram contra', o verbo concorda na terceira pessoa do plural, pois a primeira pessoa não prevalece sobre a terceira.","1ª pessoa prevalece.","terceira pessoa prevalece sobre a primeira")
CN(7,"norma_culta",3,"Em 'Votos, emendas, destaques, tudo se resolveu em plenário', o verbo concorda com o pronome 'tudo', que resume os elementos enumerados.","Em 'Votos, emendas, destaques, tudo se resolveu em plenário', o verbo deveria estar no plural, concordando com os elementos enumerados.","'Tudo' resume o sujeito.","ignora o pronome resumitivo")
# átomo 8: impessoais e 'se'
CN(8,"norma_culta",2,"Em 'Há muitos projetos em tramitação', o verbo haver, com sentido de existir, é impessoal e fica no singular.","Em 'Há muitos projetos em tramitação', o verbo haver deveria ir ao plural para concordar com 'projetos'.","Haver = existir: impessoal.","flexiona haver impessoal")
CN(8,"norma_culta",2,"Em 'Faz dois anos que a lei foi publicada', o verbo fazer, indicando tempo decorrido, é impessoal e fica no singular.","Em 'Fazem dois anos que a lei foi publicada', o verbo fazer concorda com 'dois anos', sendo correta a forma no plural.","Fazer (tempo): impessoal.","flexiona fazer impessoal")
CN(8,"norma_culta",3,"A frase 'Existem falhas no sistema' atende à norma-padrão, pois o verbo existir concorda com o sujeito 'falhas'.","A frase 'Existe falhas no sistema' atende à norma-padrão, pois o verbo existir é impessoal.","Existir não é impessoal.","trata existir como impessoal")
CN(8,"confusao_instituto",3,"Em 'Vendem-se casas', o 'se' é partícula apassivadora, e o verbo concorda com o sujeito 'casas'.","Em 'Vendem-se casas', o 'se' é índice de indeterminação do sujeito, e o verbo deveria ficar no singular.","Verbo transitivo direto + se = passiva.","confunde apassivadora e indeterminação")
CN(8,"confusao_instituto",3,"Em 'Alugam-se salas comerciais', o verbo concorda com o sujeito paciente, pois o 'se' é partícula apassivadora.","A frase 'Aluga-se salas comerciais' atende à norma-padrão, pois o 'se' indetermina o sujeito.","Transitivo direto: concorda com o sujeito.","aceita singular com apassivadora")
CN(8,"confusao_instituto",3,"Em 'Precisa-se de servidores', o verbo fica no singular, pois o 'se' indetermina o sujeito e o verbo é transitivo indireto.","Em 'Precisam-se de servidores', o verbo vai ao plural, pois o 'se' é apassivador e concorda com 'servidores'.","Transitivo indireto + se: singular.","flexiona verbo com indeterminação")
CN(8,"norma_culta",2,"Em 'Trata-se de projetos relevantes', o verbo fica no singular, pois não há sujeito determinado.","Em 'Tratam-se de projetos relevantes', o verbo fica no plural, pois concorda com 'projetos'.","Tratar-se de: singular.","flexiona o verbo tratar-se")
# átomo 9: coletivos, mais de um, um dos que, cerca de, que/quem, cada um
CN(9,"excecao_omitida",3,"Em 'A maioria dos deputados votou a favor', o verbo no singular concorda com o núcleo 'maioria', sendo também admitido o plural.","Em 'A maioria dos deputados votou a favor', o verbo no singular concorda com o núcleo 'maioria', mas o plural é incorreto.","Coletivo + especificador: ambos.","veta o plural")
CN(9,"norma_culta",3,"Em 'Mais de um deputado votou contra', o verbo fica no singular.","Em 'Mais de um deputado votaram contra', o verbo fica no plural, concordando com a ideia de pluralidade.","'Mais de um' + singular: verbo singular.","verbo plural com 'mais de um'")
CN(9,"norma_culta",4,"Em 'Um dos deputados que votaram contra era do partido X', o verbo da oração adjetiva concorda no plural com 'deputados'.","Em 'Um dos deputados que votaram contra era do partido X', o verbo da oração adjetiva deveria estar no singular, concordando com 'um'.","'Um dos que': plural.","singular com 'um dos que'")
CN(9,"norma_culta",3,"Em 'Cerca de cem deputados faltaram', o verbo concorda com o numeral que a expressão 'cerca de' antecede.","Em 'Cerca de cem deputados faltaram', o verbo deveria estar no singular, concordando com o substantivo 'cerca'.","'Cerca de' não é o núcleo.","concorda com 'cerca'")
CN(9,"norma_culta",3,"Em 'Somos nós que decidimos', o verbo da oração adjetiva concorda com o pronome 'nós', antecedente do relativo 'que'.","Em 'Somos nós que decidem', o verbo da oração adjetiva concorda com o relativo 'que', na terceira pessoa.","'Que' retoma o antecedente.","concorda com o relativo")
CN(9,"norma_culta",2,"Em 'Cada um dos deputados apresentou emendas', o verbo concorda no singular com 'cada um'.","Em 'Cada um dos deputados apresentaram emendas', o verbo concorda no plural com 'deputados'.","'Cada um': singular.","plural com 'cada um'")
CN(9,"norma_culta",2,"Em 'Os Estados Unidos apoiaram a medida', o verbo concorda no plural com o nome próprio acompanhado de artigo no plural.","Em 'Os Estados Unidos apoiou a medida', o verbo concorda no singular com o nome próprio, ainda que o artigo esteja no plural.","Artigo plural: verbo plural.","singular com artigo plural")
CN(9,"norma_culta",2,"Em 'Mais de dez deputados faltaram', o verbo concorda no plural com o numeral.","Em 'Mais de dez deputados faltou', o verbo concorda no singular com 'mais de'.","'Mais de dez': plural.","singular com numeral plural")
# átomo 10: horas
CN(10,"norma_culta",2,"A frase 'Era uma hora quando a sessão terminou' atende à norma-padrão, pois o verbo concorda com o numeral que indica a hora.","A frase 'Eram uma hora quando a sessão terminou' atende à norma-padrão, pois o verbo vai ao plural em indicações de hora.","Verbo ser com hora: concorda com o numeral.","plural com uma hora")
CN(10,"norma_culta",3,"A frase 'Bateram cinco horas no relógio da Câmara' atende à norma-padrão, pois o verbo bater concorda com o numeral que indica as horas.","A frase 'Bateu cinco horas no relógio da Câmara' atende à norma-padrão, pois o verbo bater é impessoal.","Bater/dar/soar + horas: concorda.","trata bater como impessoal")
# átomo 11: nominal
CN(11,"norma_culta",2,"A frase 'É proibida a entrada de estranhos' atende à norma-padrão, pois há artigo antes do substantivo e o adjetivo concorda com ele.","A frase 'É proibido a entrada de estranhos' atende à norma-padrão, pois a expressão 'é proibido' é invariável em qualquer contexto.","Com artigo, concorda.","invariável mesmo com artigo")
CN(11,"norma_culta",2,"A frase 'Ela está meio cansada' atende à norma-padrão, pois 'meio' é advérbio e fica invariável.","A frase 'Ela está meia cansada' atende à norma-padrão, pois 'meio' concorda com o adjetivo.","'Meio' advérbio: invariável.","flexiona 'meio' advérbio")
CN(11,"norma_culta",2,"A frase 'Seguem anexos os documentos solicitados' atende à norma-padrão, pois 'anexo' concorda com o substantivo.","A frase 'Seguem anexo os documentos solicitados' atende à norma-padrão, pois 'anexo' é invariável.","'Anexo' é adjetivo: concorda.","deixa 'anexo' invariável")
