CN(11,"norma_culta",3,"Em 'Elas estão bastante preocupadas', 'bastante' é advérbio e fica invariável.","A frase 'Elas estão bastantes preocupadas' atende à norma-padrão, pois 'bastante' concorda com 'preocupadas'.","'Bastante' modificando adjetivo: invariável.","flexiona 'bastante' advérbio")
CN(11,"norma_culta",1,"A frase 'Havia menos servidores na sessão' atende à norma-padrão, pois 'menos' é invariável.","A frase 'Havia menas servidoras na sessão' atende à norma-padrão, pois 'menos' concorda com o substantivo feminino.","'Menos' é invariável.","flexiona 'menos'")
CN(11,"norma_culta",3,"Em 'Obtivemos as melhores condições possíveis', 'possíveis' concorda com 'condições'.","Em 'Obtivemos as melhores condições possível', 'possível' é invariável e atende à norma-padrão.","Adjetivo concorda.","deixa 'possível' invariável")
